import React, { createContext, useContext, useState, useEffect } from 'react';

// Create context
const MosqueContext = createContext();

// Context provider
export const MosqueProvider = ({ children }) => {
    const [mosques, setMosques] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [favorites, setFavorites] = useState([]);
    
    // Load favorite mosques from localStorage on mount
    useEffect(() => {
        const savedFavorites = localStorage.getItem('favoriteMosques');
        if (savedFavorites) {
            setFavorites(JSON.parse(savedFavorites));
        }
        
        // In a real app, this would be an API call to fetch mosques
        // For now, we'll just simulate it with a timeout
        const fetchMosques = async () => {
            try {
                setLoading(true);
                // Simulate API call
                await new Promise(resolve => setTimeout(resolve, 1000));
                
                // In a real app, we'd fetch from an API here
                const mockMosques = [
                    {
                        id: '1',
                        name: 'Islamic Center of Orlando',
                        address: '1089 N Goldenrod Rd, Orlando, FL 32807',
                        phone: '(407) 273-8363',
                        website: 'http://www.icorlando.org',
                        rating: 4.8,
                        reviewCount: 156,
                        image: 'https://picsum.photos/id/1071/600/400',
                        distance: 2.3,
                        type: 'masjid',
                    },
                    {
                        id: '2',
                        name: 'Masjid Al-Rahman',
                        address: '427 S Bumby Ave, Orlando, FL 32806',
                        phone: '(407) 895-0102',
                        website: 'http://www.masjidalrahman.org',
                        rating: 4.5,
                        reviewCount: 118,
                        image: 'https://picsum.photos/id/1081/600/400',
                        distance: 3.7,
                        type: 'masjid',
                    },
                    {
                        id: '3',
                        name: 'Muslim Community Center of Orlando',
                        address: '11543 Ruby Lake Rd, Orlando, FL 32836',
                        phone: '(407) 277-9388',
                        website: 'http://www.mccoflorlando.org',
                        rating: 4.6,
                        reviewCount: 83,
                        image: 'https://picsum.photos/id/164/600/400',
                        distance: 5.1,
                        type: 'community_center',
                    },
                ];
                
                setMosques(mockMosques);
                setLoading(false);
            } catch (err) {
                setError('Failed to load mosque data. Please try again later.');
                setLoading(false);
            }
        };
        
        fetchMosques();
    }, []);
    
    // Toggle a mosque as favorite
    const toggleFavorite = (mosqueId) => {
        setFavorites(prevFavorites => {
            let newFavorites;
            if (prevFavorites.includes(mosqueId)) {
                newFavorites = prevFavorites.filter(id => id !== mosqueId);
            } else {
                newFavorites = [...prevFavorites, mosqueId];
            }
            
            // Save to localStorage
            localStorage.setItem('favoriteMosques', JSON.stringify(newFavorites));
            return newFavorites;
        });
    };
    
    // Define what we're exposing from context
    const value = {
        mosques,
        loading,
        error,
        favorites,
        toggleFavorite
    };
    
    return (
        <MosqueContext.Provider value={value}>
            {children}
        </MosqueContext.Provider>
    );
};

// Create a hook for easy context use
export const useMosqueContext = () => {
    const context = useContext(MosqueContext);
    if (!context) {
        throw new Error('useMosqueContext must be used within a MosqueProvider');
    }
    return context;
};

export default MosqueContext;